import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;

import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;

public final class StdDraw {
    public static final Color BLACK = Color.BLACK;

    private static final Object LOCK = new Object();
    private static final int DEFAULT_SIZE = 800;

    private static JFrame frame;
    private static DrawPanel panel;
    private static BufferedImage offscreenImage;
    private static BufferedImage onscreenImage;
    private static Graphics2D offscreen;
    private static Graphics2D onscreen;

    private static double xmin = 0.0;
    private static double xmax = 1.0;
    private static double ymin = 0.0;
    private static double ymax = 1.0;

    private static Color penColor = Color.WHITE;
    private static boolean doubleBuffering = false;

    private static volatile double mouseX = Double.NaN;
    private static volatile double mouseY = Double.NaN;
    private static volatile boolean mousePressed = false;

    static {
        init();
    }

    private StdDraw() {
    }

    private static void init() {
        if (panel != null) {
            return;
        }

        panel = new DrawPanel();
        panel.setPreferredSize(new Dimension(DEFAULT_SIZE, DEFAULT_SIZE));
        panel.setBackground(Color.BLACK);
        panel.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                mousePressed = true;
                updateMousePosition(e.getX(), e.getY());
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                mousePressed = false;
                updateMousePosition(e.getX(), e.getY());
            }
        });
        panel.addMouseMotionListener(new MouseAdapter() {
            @Override
            public void mouseMoved(MouseEvent e) {
                updateMousePosition(e.getX(), e.getY());
            }

            @Override
            public void mouseDragged(MouseEvent e) {
                mousePressed = true;
                updateMousePosition(e.getX(), e.getY());
            }
        });

        frame = new JFrame("StdDraw");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setContentPane(panel);
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);

        createBuffers(DEFAULT_SIZE, DEFAULT_SIZE);
        clear(Color.BLACK);
        show();
    }

    private static void createBuffers(int width, int height) {
        synchronized (LOCK) {
            if (offscreen != null) {
                offscreen.dispose();
            }
            if (onscreen != null) {
                onscreen.dispose();
            }

            offscreenImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
            onscreenImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
            offscreen = offscreenImage.createGraphics();
            onscreen = onscreenImage.createGraphics();

            configureGraphics(offscreen);
            configureGraphics(onscreen);

            panel.setPreferredSize(new Dimension(width, height));
            panel.revalidate();
            frame.pack();
        }
    }

    private static void configureGraphics(Graphics2D g) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g.setStroke(new BasicStroke(1.0f));
    }

    public static void setCanvasSize(int width, int height) {
        ensureReady();
        createBuffers(Math.max(1, width), Math.max(1, height));
    }

    public static void setXscale(double min, double max) {
        xmin = min;
        xmax = max;
    }

    public static void setYscale(double min, double max) {
        ymin = min;
        ymax = max;
    }

    public static void enableDoubleBuffering() {
        doubleBuffering = true;
    }

    public static void clear(Color color) {
        ensureReady();
        synchronized (LOCK) {
            offscreen.setColor(color);
            offscreen.fillRect(0, 0, offscreenImage.getWidth(), offscreenImage.getHeight());
        }
    }

    public static void clear() {
        clear(Color.BLACK);
    }

    public static void setPenColor(int red, int green, int blue) {
        penColor = new Color(clamp(red), clamp(green), clamp(blue));
    }

    public static void setPenColor(Color color) {
        penColor = color;
    }

    public static void filledCircle(double x, double y, double radius) {
        ensureReady();
        synchronized (LOCK) {
            offscreen.setColor(penColor);
            double px = scaleX(x);
            double py = scaleY(y);
            double pr = radius * Math.min(pixelScaleX(), pixelScaleY());
            double left = px - pr;
            double top = py - pr;
            double size = 2.0 * pr;
            offscreen.fill(new Ellipse2D.Double(left, top, size, size));
        }
    }

    public static void show() {
        ensureReady();
        synchronized (LOCK) {
            onscreen.drawImage(offscreenImage, 0, 0, null);
            panel.repaint();
        }
        if (doubleBuffering) {
            java.awt.Toolkit.getDefaultToolkit().sync();
        }
    }

    public static void pause(int milliseconds) {
        try {
            Thread.sleep(Math.max(0, milliseconds));
        } catch (InterruptedException interruptedException) {
            Thread.currentThread().interrupt();
        }
    }

    public static double mouseX() {
        return mouseX;
    }

    public static double mouseY() {
        return mouseY;
    }

    public static boolean isMousePressed() {
        return mousePressed;
    }

    private static void updateMousePosition(int pixelX, int pixelY) {
        double width = Math.max(1.0, offscreenImage.getWidth() - 1.0);
        double height = Math.max(1.0, offscreenImage.getHeight() - 1.0);
        double x = xmin + (xmax - xmin) * (pixelX / width);
        double y = ymax - (ymax - ymin) * (pixelY / height);
        mouseX = x;
        mouseY = y;
    }

    private static double scaleX(double x) {
        return (x - xmin) / (xmax - xmin) * offscreenImage.getWidth();
    }

    private static double scaleY(double y) {
        return (ymax - y) / (ymax - ymin) * offscreenImage.getHeight();
    }

    private static double pixelScaleX() {
        return offscreenImage.getWidth() / (xmax - xmin);
    }

    private static double pixelScaleY() {
        return offscreenImage.getHeight() / (ymax - ymin);
    }

    private static int clamp(int value) {
        if (value < 0) return 0;
        if (value > 255) return 255;
        return value;
    }

    private static void ensureReady() {
        if (panel == null) {
            init();
        }
    }

    private static final class DrawPanel extends JPanel {
        @Override
        protected void paintComponent(java.awt.Graphics graphics) {
            super.paintComponent(graphics);
            if (onscreenImage != null) {
                graphics.drawImage(onscreenImage, 0, 0, null);
            }
        }
    }
}

